/// <summary>
/// Create a number sequence reference for the default scope.
/// </summary>
/// <param name = "_edt">The extended data type of the number seqeunce.</param>
private static void initializeNumberSequence(ExtendedTypeId _edt, boolean resetWizardDefaults)
{
    NumberSequenceReference sequenceReference;
    NumberSequenceTable sequence;
    NumberSeqDatatype dataTypeObject;
    NumberSequenceDatatype dataTypeRecord;
    NumberSeqScope scope;

    if (_edt)
    {
        sequenceReference = NumberSequenceTable::autoCreate(_edt);
        if (sequenceReference && resetWizardDefaults)
        {
            ttsbegin;
            sequence = NumberSequenceTable::find(sequenceReference.NumberSequenceId, true);
            if (sequence)
            {
                dataTypeObject = NumberSeqDatatype::construct();
                dataTypeObject.find(_edt);
                scope = NumberSeqScopeFactory::createDefaultScope(dataTypeObject);

                dataTypeRecord = NumberSequenceDatatype::find(dataTypeObject.parmRecId());

                sequence.AllowChangeDown = dataTypeRecord.WizardAllowChangeDown;
                sequence.AllowChangeUp = dataTypeRecord.WizardAllowChangeUp;
                sequence.AnnotatedFormat = dataTypeRecord.wizardAnnotatedFormat(scope, dataTypeRecord.wizardHighest, true);
                sequence.Continuous = dataTypeRecord.WizardContinuous;
                sequence.FetchAheadQty = dataTypeRecord.WizardFetchAheadQty;
                sequence.Format = dataTypeRecord.wizardFormat(scope, dataTypeRecord.WizardHighest, true);
                sequence.Highest = dataTypeRecord.WizardHighest;
                sequence.Lowest = dataTypeRecord.WizardLowest;
                sequence.Manual = dataTypeRecord.WizardManual;
                sequence.NextRec = 1;
                sequence.update();
            }
            ttscommit;
        }
    }
}

public static void main(Args _args)
{
    FmDataHelper::cleanupBrokenNumberSequences();

    FMDataHelper::ConfigureTotalsEngine();

    FmDataHelper::populateData_Silent();
}

public static void ConfigureTotalsEngine()
{
    FMParameters FMParam = FMParameters::find(true);

    ttsbegin;
    FMParam.TotalsEngine = "Default";
    FMParam.update();
    ttscommit;
}

/// <summary>
/// Some of the NumberSequenceDatatype records referr to non-existent modules.
/// This method deletes them so that number sequence setup can succeed.
/// </summary>
private static void cleanupBrokenNumberSequences()
{
    NumberSequenceDatatype nsdt;

    ttsbegin;

    delete_from nsdt where nsdt.module == -1;

    ttscommit;
}

public static void cleanup() 
{
    FMVehicle vehicle;

    FMRental rental;
    FMRentalCharge rentalCharge;
    FMChargeType chargetype;
    FMCustGroup custGroup;

    FMCustomer customer;
    FMVehicleMake make;
    FMVehicleModel model;
    FMSUVSafetyRating safetyRating;
    FMVehicleRate vehicleRate;

    FMComments com; 
    FMCustomerComments custComments; 

    FMAddressTable address;
    FMPaymentInformation payments;
    FMModelRate makeModelRate;
    FMCarColor carColors;

    OMUserRoleOrganization userRoleOrganization;

    delete_from address;
    delete_from payments;
    delete_from makeModelRate;
    delete_from carColors;
    delete_from custComments; 
    delete_from com; 


    delete_from vehicle;

    delete_from rental;
    delete_from rentalCharge;
    delete_from chargetype;

    delete_from customer;
    delete_from custGroup;

    delete_from make;
    delete_from model;

    delete_from safetyRating;

    delete_from vehicleRate;
    delete_from userRoleOrganization;
}

public static void createOperatingUnit(DirPartyName name, OMOperatingUnitType ouType, NameAlias nameAlias)
{
    OMOperatingUnit ou;

    select firstonly ou where ou.Name == name;
    if (!ou)
    {
        ou.omOperatingUnitType = ouType;
        ou.Name = name;
        ou.NameAlias = nameAlias;
        ou.insert();
        ou.clear();
    }

}

public static boolean IsManagedDataAccess()
{
    return Microsoft.Dynamics.Ax.Xpp.DataAccess.Helper::IsManagedDataAccess();
}

