public static void fmChargeTypeInsert()
{
    FMChargeType chargetype;
    container imageContainer;
    resourceNode resourceNode;

    //PopulateChargeType
    ttsbegin;
    chargetype.ChargeType = 'Car pickup';
    chargetype.Description = 'We arrange pickup from another location.';
    chargetype.PerUnitAmount = 35;
    chargetype.DefaultQuantity = 1;
    resourceNode = SysResource::getResourceNode(resourceStr(VehiclePickup));
    if (resourceNode != null)
    {
        imageContainer = SysResource::getResourceNodeData(resourceNode);
        chargetype.Image = imageContainer;
    }
    chargetype.insert();

    chargetype.ChargeType = 'Carbon fee';
    chargetype.Description = 'Help offset carbon emissions.';
    chargetype.PerUnitAmount = 5;
    chargetype.DefaultQuantity = 1;
    resourceNode = SysResource::getResourceNode(resourceStr(CarbonFee));
    if (resourceNode != null)
    {
        imageContainer = SysResource::getResourceNodeData(resourceNode);
        chargetype.Image = imageContainer;
    }
    chargetype.insert();

    chargetype.ChargeType = 'Tank refill';
    chargetype.Description = 'We refill the gas tank.';
    chargetype.PerUnitAmount = 40;
    chargetype.DefaultQuantity = 1;
    resourceNode = SysResource::getResourceNode(resourceStr(Refuel));
    if (resourceNode != null)
    {
        imageContainer = SysResource::getResourceNodeData(resourceNode);
        chargetype.Image = imageContainer;
    }
    chargetype.insert();

    // former Addons
    chargetype.ChargeType = 'Tire Chains';
    chargetype.Description = 'A set of chains for snowy destinations.';
    chargetype.DefaultQuantity = 4;
    chargetype.PerUnitAmount = 2.0;
    resourceNode = SysResource::getResourceNode(resourceStr(TireChains));
    if (resourceNode != null)
    {
        imageContainer = SysResource::getResourceNodeData(resourceNode);
        chargetype.Image = imageContainer;
    }
    chargetype.insert();

    chargetype.ChargeType = 'Child Seat';
    chargetype.Description = 'Child seats for small children.';
    chargetype.DefaultQuantity = 1;
    chargetype.PerUnitAmount = 10.0;
    resourceNode = SysResource::getResourceNode(resourceStr(ChildSeat));
    if (resourceNode != null)
    {
        imageContainer = SysResource::getResourceNodeData(resourceNode);
        chargetype.Image = imageContainer;
    }
    chargetype.insert();

    chargetype.ChargeType = 'GPS';
    chargetype.Description = 'Comes preloaded with a local map.';
    chargetype.PerUnitAmount = 20.0;
    chargetype.DefaultQuantity = 1;
    resourceNode = SysResource::getResourceNode(resourceStr(GPS));
    if (resourceNode != null)
    {
        imageContainer = SysResource::getResourceNodeData(resourceNode);
        chargetype.Image = imageContainer;
    }
    chargetype.insert();

    chargetype.ChargeType = 'Satellite Radio';
    chargetype.Description = 'Satellite radio provides over 50 channels.';
    chargetype.PerUnitAmount = 15.0;
    chargetype.DefaultQuantity = 1;
    resourceNode = SysResource::getResourceNode(resourceStr(SatelliteRadio));
    if (resourceNode != null)
    {
        imageContainer = SysResource::getResourceNodeData(resourceNode);
        chargetype.Image = imageContainer;
    }
    chargetype.insert();
    ttscommit;

}

