public static void fmRentalAndRentalChargeInsert()
{
    List scenarioList = new List(Types::Class);

    void process()
    {
        FMRentalScenarios rentalScarios = new FMRentalScenarios();
        FMRentalDetails rentalDtCur;

        ListEnumerator en = scenarioList.getEnumerator();
        while (en.moveNext())
        {
            // access the current entry in the list of scenarios
            rentalDtCur = en.current();                

            // insert the active rental scenario
            rentalScarios.insertRentalEntity(rentalDtCur);
