public static void numberSequenceSetup()
{
    NumberSeqScope scope;
    MenuFunction wizard = new MenuFunction('NumberSequenceWizard', MenuItemType::Action);

    NumberSeqModuleRental moduleRental = new NumberSeqModuleRental();
    moduleRental.load();

    scope = NumberSeqScopeFactory::createGlobalScope();
    NumberSequenceTable::autoCreate(extendedTypeNum(FMRentalId), scope);
    moduleRental.loadModule();

    wizard.run();

}

