    FMDataHelper::initializeNumberSequence(extendedtypenum(OMOperatingUnitNumber), false);
    FMDataHelper::initializeNumberSequence(extendedtypenum(DirPartyNumber), false);
    FMDataHelper::initializeNumberSequence(extendedtypenum(LogisticsLocationId), false);

    info('Setup workflow number sequences... ');
    FMDataHelperWF::SetupWorkflowNumberSequences();
}

public static void orgModelInsert()
{

    OMHierarchyType omht;
    OMHierarchyPurpose omhp;

    CompanyInfo ci;

    OMOrganizationHierarchy hierarchy;
    OMOrganizationNode pnode, cnode, tnode;
    OMMultipleHierarchy     hierarchyHelper;
    OMOperatingUnit ou;




    int64 recId;



    //////////////////////////////////////////////////////////////////////////////////
    // Clear out old data
    //////////////////////////////////////////////////////////////////////////////////
    ttsbegin;

    select firstonly omht where omht.Name == 'Fleet Management Organization Hierarchy';
    recId = omht.RecId;
    delete_from omhp where omhp.HierarchyType == recId;
    delete_from omht where omht.Name == 'Fleet Management Organization Hierarchy';

    ttscommit;

    //////////////////////////////////////////////////////////////////////////////////
    // Create Hierarchy
    //////////////////////////////////////////////////////////////////////////////////
    ttsbegin;

    hierarchyHelper = OMMultipleHierarchy::construct('Fleet Management Organization Hierarchy');
    hierarchy = new OMOrganizationHierarchy( hierarchyHelper );
    hierarchy.enterEditMode(false);

    //Create a legal entity

    select firstonly ci where ci.DataArea == 'FM';
    if (!ci)
    {

        ci.Name = 'FM Inc Corporate Office';
        ci.DataArea = 'FM';
        ci.insert();
    }

    // Create Branches


    FMDataHelper::createOperatingUnit('California',OMOperatingUnitType::OMBranchFM, 'Californa');
    FMDataHelper::createOperatingUnit('Washington',OMOperatingUnitType::OMBranchFM, 'Washington');

    // Create Locations
    FMDataHelper::createOperatingUnit('Redmond', OMOperatingUnitType::OMRentalLocationFM, 'Redmond');
    FMDataHelper::createOperatingUnit('SEATAC Airport', OMOperatingUnitType::OMRentalLocationFM, 'SEATAC');
    FMDataHelper::createOperatingUnit('Downtown Seattle', OMOperatingUnitType::OMRentalLocationFM, 'Seattle');
    FMDataHelper::createOperatingUnit('San Jose', OMOperatingUnitType::OMRentalLocationFM, 'SJC');
    FMDataHelper::createOperatingUnit('Los Angeles', OMOperatingUnitType::OMRentalLocationFM, 'Los Angeles');
    FMDataHelper::createOperatingUnit('LAX Airport', OMOperatingUnitType::OMRentalLocationFM, 'LAX');


    ttscommit;

    //////////////////////////////////////////////////////////////////////////////////
    // Link nodes in hierarchy
    //////////////////////////////////////////////////////////////////////////////////


    // Get and set root LE node
    select firstonly ci where (ci.Name == 'FM Inc Corporate Office' && ci.DataArea == 'FM');
    pnode = hierarchy.addRootNode(ci.RecId);
    tnode = pnode;

    // Add California Branch
    select firstonly ou where ou.Name == 'California';
    cnode = hierarchy.createNode(ou.RecId);
    hierarchy.addChild(pnode, cnode);

    pnode = cnode;

    select firstonly ou where ou.Name == 'San Jose';
    cnode = hierarchy.createNode(ou.RecId);
    hierarchy.addChild(pnode, cnode);

    select firstonly ou where ou.Name == 'Los Angeles';
    cnode = hierarchy.createNode(ou.RecId);
    hierarchy.addChild(pnode, cnode);

    select firstonly ou where ou.Name == 'LAX Airport';
    cnode = hierarchy.createNode(ou.RecId);
    hierarchy.addChild(pnode, cnode);


    // Add Washington Branch
    select firstonly ou where ou.Name == 'Washington';
    cnode = hierarchy.createNode(ou.RecId);
    hierarchy.addChild(tnode, cnode);

    pnode = cnode;

    select firstonly ou where ou.Name == 'Redmond';
    cnode = hierarchy.createNode(ou.RecId);
    hierarchy.addChild(pnode, cnode);

    select firstonly ou where ou.Name == 'SEATAC Airport';
    cnode = hierarchy.createNode(ou.RecId);
    hierarchy.addChild(pnode, cnode);

    select firstonly RecId from ou where ou.Name == 'Downtown Seattle';
    cnode = hierarchy.createNode(ou.RecId);
    hierarchy.addChild(pnode, cnode);

    // Publish it!
    //hierarchy.Publish( DateTimeUtil::utcNow(), '');
    hierarchy.publish(2011-01-01T00:00:00,'');
}

public static void populateData()
{
    info('Dropping all tables');
    FMDataHelper::cleanup();

    info('Setting Up Number Sequences - first pass...');
    FMDataHelper::numberSequenceSetup();

    info('Creating Org Model...');
    FMDataHelper::orgModelInsert();

    info('Setting Up Number Sequences - second pass...');
    FMDataHelper::numberSequenceSetup();

    //FM Table inserts

    info('Creating Colors...');
    FMDataHelper::fmColorInsert();

    info('Creating Customer Groups...');
    FMDataHelper::fmCustGroupInsert();

    info('Creating customers...');
    FMDataHelper::fmCustomerInsert();

    info('Creating Make/Model...');
    FMDataHelper::fmMakeModelInsert();

    info('Creating SUV Safety Rating...');
    FMDataHelper::fmsuvSafetyRatingInsert();

    info('Creating Truck...');
    FMDataHelper::fmVehicleTruckInsert();

    info('Creating Cars...');
    FMDataHelper::fmCarClassInsert();

    info('Creating SUVs...');
    FMDataHelper::fmsuvInsert();

    info('Creating Vehicle Rate...');
    FMDataHelper::fmVehicleRateInsert();

    info('Creating Charge Type...');
