public static void setSecurityRoles()
{
    SecurityRole        fmServiceTech;
    SecurityRole        fmClerk;
    SecurityRole        fmManager;
    SecurityRole        systemUser;
    SecurityRole        admin;
    SecurityUserRole    userRoles;

    ttsbegin;

    select firstonly RecId from fmServiceTech  where fmServiceTech.AotName == 'FMServiceTech';
    select firstonly RecId from fmClerk        where fmClerk.AotName       == 'FMClerk';
    select firstonly RecId from fmManager      where fmManager.AotName     == 'FMManager';
    select firstonly RecId from systemUser     where systemUser.AotName    == 'SystemUser';
    select firstonly RecId from admin          where admin.AotName         == '-SYSADMIN-';

    // Delete existing user roles
    delete_from userRoles where (userRoles.User != 'Admin' && userRoles.SecurityRole != admin.RecId);

    // Add new Roles
    select firstonly forupdate userRoles;
    userRoles.User = 'serv';
    userRoles.SecurityRole = systemUser.RecId;
    userRoles.insert();

    select firstonly forupdate userRoles;
    userRoles.User = 'serv';
    userRoles.SecurityRole = fmServiceTech.RecId;
    userRoles.insert();


    select firstonly forupdate userRoles;
    userRoles.User = 'clerk';
    userRoles.SecurityRole = systemUser.RecId;
    userRoles.insert();

    select firstonly forupdate userRoles;
    userRoles.User = 'clerk';
    userRoles.SecurityRole = fmClerk.RecId;
    userRoles.insert();

    select firstonly forupdate userRoles;
    userRoles.User = 'mgr1';
    userRoles.SecurityRole = systemUser.RecId;
    userRoles.insert();

    select firstonly forupdate userRoles;
    userRoles.User = 'mgr1';
    userRoles.SecurityRole = fmManager.RecId;
    userRoles.insert();

    select firstonly forupdate userRoles;
    userRoles.User = 'mgr2';
    userRoles.SecurityRole = systemUser.RecId;
    userRoles.insert();

    select firstonly forupdate userRoles;
    userRoles.User = 'mgr2';
    userRoles.SecurityRole = fmManager.RecId;
    userRoles.insert();

    /************  Setup roles for FMSvcTech *************/
    delete_from userRoles where userRoles.User == #FMSvcTechUserId;
    select firstonly forupdate userRoles;
    userRoles.User = #FMSvcTechUserId;
    userRoles.SecurityRole = fmServiceTech.RecId;
    userRoles.insert();

    select firstonly forupdate userRoles;
    userRoles.User = #FMSvcTechUserId;
    userRoles.SecurityRole = systemUser.RecId;
    userRoles.insert();

    select firstonly forupdate userRoles;
    userRoles.User = #FMSvcTechUserId;
    userRoles.SecurityRole = admin.RecId;
    userRoles.insert();

    /************  Setup roles for FMClerk *************/
    delete_from userRoles where userRoles.User == #FMClerkUserId;
    select firstonly forupdate userRoles;
    userRoles.User = #FMClerkUserId;
    userRoles.SecurityRole = fmClerk.RecId;
    userRoles.insert();

    select firstonly forupdate userRoles;
    userRoles.User = #FMClerkUserId;
    userRoles.SecurityRole = systemUser.RecId;
    userRoles.insert();

    select firstonly forupdate userRoles;
    userRoles.User = #FMClerkUserId;
    userRoles.SecurityRole = admin.RecId;
    userRoles.insert();

    /************  Setup roles for FMManager *************/
    delete_from userRoles where userRoles.User == #FMManagerUserId;
    select firstonly forupdate userRoles;
    userRoles.User = #FMManagerUserId;
    userRoles.SecurityRole = fmManager.RecId;
    userRoles.insert();

    select firstonly forupdate userRoles;
    userRoles.User = #FMManagerUserId;
    userRoles.SecurityRole = systemUser.RecId;
    userRoles.insert();

    select firstonly forupdate userRoles;
    userRoles.User = #FMManagerUserId;
    userRoles.SecurityRole = admin.RecId;
    userRoles.insert();

    ttscommit;
}

public static void setUserLocations()
{
    SecurityRole        fmServiceTech;
    SecurityRole        fmClerk;
    SecurityRole        fmManager1;
    SecurityRole        fmManager2;
    SecurityRole        fmSelfService;

    OMOperatingUnit         redmondLocation;
    OMOperatingUnit         seatacLocation;
    OMOperatingUnit         wa;
    OMOperatingUnit         ca;

    OMUserRoleOrganization  userRoleOrg;
    OMHierarchyType         omht;
    OMHierarchyPurpose      omhp;

    ttsbegin;

    select firstonly RecId from fmServiceTech  where fmServiceTech.AotName == 'FMServiceTech';
    select firstonly RecId from fmClerk        where fmClerk.AotName      == 'FMClerk';
    select firstonly RecId from fmManager1     where fmManager1.AotName    == 'FMManager';
    select firstonly RecId from fmManager2     where fmManager2.AotName   == 'FMManager';
    select firstonly RecId from fmSelfService  where fmSelfService.AotName== 'FMSelfServ';

    select firstonly redmondLocation where redmondLocation.Name == 'Redmond';
    select firstonly seatacLocation  where seatacLocation.Name  == 'SEATAC Airport';

    select firstonly RecId from wa where wa.Name == 'Washington';
    select firstonly RecId from ca  where ca.Name  == 'California';
    select firstonly RecId from omht where omht.Name == 'Fleet Management Organization Hierarchy';

    // Start Fresh
    delete_from userRoleOrg;

    // Add user-role-location links
    select firstonly forupdate userRoleOrg;
    userRoleOrg.SecurityRole = fmServiceTech.RecId;
    userRoleOrg.User = 'serv';
    userRoleOrg.omInternalOrganization = redmondLocation.RecId;
    userRoleOrg.omHierarchyType = omht.RecId;
    userRoleOrg.insert();

    select firstonly forupdate userRoleOrg;
    userRoleOrg.SecurityRole = fmClerk.RecId;
    userRoleOrg.User = 'clerk';
    userRoleOrg.omInternalOrganization = redmondLocation.RecId;
    userRoleOrg.omHierarchyType = omht.RecId;
    userRoleOrg.insert();

    select firstonly forupdate userRoleOrg;
    userRoleOrg.SecurityRole = fmManager1.RecId;
    userRoleOrg.User = 'mgr1';
    userRoleOrg.omInternalOrganization = wa.RecId;
    userRoleOrg.omHierarchyType = omht.RecId;
    userRoleOrg.insert();

    select firstonly forupdate userRoleOrg;
    userRoleOrg.SecurityRole = fmManager2.RecId;
    userRoleOrg.User = 'mgr2';
    userRoleOrg.omInternalOrganization = ca.RecId;
    userRoleOrg.omHierarchyType = omht.RecId;
    userRoleOrg.insert();

    select firstonly forupdate userRoleOrg;
    userRoleOrg.SecurityRole = fmSelfService.RecId;
    userRoleOrg.User = 'self';
    userRoleOrg.omInternalOrganization = redmondLocation.RecId;
    userRoleOrg.omHierarchyType = omht.RecId;
    userRoleOrg.insert();

    select  firstonly forupdate omhp;
    omhp.HierarchyType = omht.RecId;
    omhp.HierarchyPurpose = HierarchyPurpose::Security;
    omhp.insert();

    ttscommit;
}

public static void usersInsert()
{
    #define.AdminId('Admin')
    UserInfo userInfo;
    SecurityUserRole userRole;
    SysUserInfo sysUserInfo;

    void addUser(str 20 _userId, str _userName, str _userSid, str 20 _userAlias, str _userDomain, str _defaultCompany = curext())
    {

        delete_from userRole where userRole.User == _userId;

        //Check if user already exists, and remove it
        select forupdate firstonly userInfo where userInfo.NetworkAlias == _userAlias;
        userInfo.delete();
        select forupdate firstonly sysUserInfo where sysUserInfo.Id == userInfo.Id;
        sysUserInfo.delete();


        //Copy default information from admin user
        select firstonly userInfo where userInfo.Id == #AdminId;

        //User info
        userInfo.Id = _userId;
        userInfo.Name = _userName;

        //Account information
        userInfo.Sid = _userSid;
        userInfo.NetworkAlias = _userAlias;
        userInfo.NetworkDomain = _userDomain;

        //Default company
        userInfo.Company = _defaultCompany;

        //Enable
        userInfo.Enable = NoYes::Yes;
        userInfo.EnabledOnce = NoYes::Yes;

        userInfo.insert();

        select firstonly sysUserInfo where sysUserInfo.Id == _userId;
        if(sysUserInfo.RecId == 0)
        {
            sysUserInfo.Id = _userId;
            sysUserInfo.insert();
        }
    }
}

